SourceCode.Declaration:
/// <summary>
/// Contract class containing response from inbound message processing
/// </summary>
[DataContract]
public class OMGInboundMessageResponseContract
{
    str                 response;
    boolean             processed;
    boolean             processedOk;
    OMGExecutionId      executionId;
    OMGProcessingStatus processingStatus;

}

Method.Source:
[DataMember('Response')]
public str parmResponse(str _response = response)
{
    response = _response;
    return _response;
}

[DataMember('Processed')]
public boolean parmProcessed(boolean _processed = processed)
{
    processed = _processed;
    return processed;
}

[DataMember('ProcessedOk')]
public boolean parmProcessedOk(boolean _processedOk = processedOk)
{
    processedOk = _processedOk;
    return processedOk;
}

[DataMember('ExecutionId')]
public OMGExecutionId parmExecutionId(OMGExecutionId _executionId = executionId)
{
    executionId = _executionId;
    return executionId;
}

[DataMember('ProcessingStatus')]
public OMGProcessingStatus parmProcessingStatus(OMGProcessingStatus _processingStatus = processingStatus)
{
    processingStatus = _processingStatus;
    return processingStatus;
}
